                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < R and 0 <= nc < C and not visited[nr][nc] and grid[nr][nc] == 8:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                components.append(comp)

    # Map each unique shape (normalized relative coordinates tuple) to a color
    shape_to_color = {}
    next_color = 1

    output = [[0] * C for _ in range(R)]

    for comp in components:
        min_r = min(p[0] for p in comp)
        min_c = min(p[1] for p in comp)

