def transform(grid: list[list[int]]) -> list[list[int]]:
    # Find all connected components of non-zero pixels or bounding boxes of frames.
    # Actually, we can identify the nested frames by finding all unique non-zero colors
    # and their bounding boxes, then sorting them by size (largest bounding box area first).

    from collections import defaultdict

    rows = len(grid)
    cols = len(grid[0])

    color_pixels = defaultdict(list)
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != 0:
                color_pixels[val].append((r, c))

    # Find bounding box for each color
    color_boxes = {}
    for color, pixels in color_pixels.items():
        min_r = min(p[0] for p in pixels)
        max_r = max(p[0] for p in pixels)
        min_c = min(p[1] for p in pixels)
        max_c = max(p[1] for p in pixels)
        area = (max_r - min_r + 1) * (max_c - min_c + 1)
        color_boxes[color] = {
            'min_r': min_r, 'max_r': max_r,
            'min_c': min_c, 'max_c': max_c,
            'area': area
        }

    # Sort colors by area descending (outermost first)
    sorted_colors = sorted(color_boxes.keys(), key=lambda k: color_boxes[k]['area'], reverse=True)

    # Determine output size based on the outermost box
    outer = color_boxes[sorted_colors[0]]
    h = outer['max_r'] - outer['min_r'] + 1
    w = outer['max_c'] - outer['min_c'] + 1
    size = max(h, w)

    # Build output grid layer by layer
    out = [[0] * size for _ in range(size)]

    for layer_idx, color in enumerate(sorted_colors):
        # Fill a border of thickness 1 at layer_idx, or fill if it's the innermost
        start = layer_idx
        end = size - 1 - layer_idx

        if start > end:
            break
        if start == end:
            out[start][start] = color
        else:
            for r in range(start, end + 1):
                for c in range(start, end + 1):
                    if r == start or r == end or c == start or c == end:
                        out[r][c] = color
                    elif layer_idx == len(sorted_colors) - 1:
                        # If it's the innermost and has area left, fill it
                        out[r][c] = color

    return out

